create table if not exists public.products (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, stock_quantity numeric not null default 0, critical_stock numeric not null default 5, purchase_price numeric not null default 0, sale_price numeric not null default 0, created_at timestamptz not null default now());
create table if not exists public.parties (id uuid primary key default gen_random_uuid(), name text not null, phone text, email text, note text, created_at timestamptz not null default now());
create table if not exists public.stock_movements (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, party_id uuid references public.parties(id) on delete set null, type text not null check(type in ('in','out')), quantity numeric not null check(quantity>0), note text, created_at timestamptz not null default now());
alter table public.products enable row level security; alter table public.parties enable row level security; alter table public.stock_movements enable row level security;
drop policy if exists p1 on public.products; drop policy if exists p2 on public.products; drop policy if exists p3 on public.products; drop policy if exists p4 on public.products;
drop policy if exists c1 on public.parties; drop policy if exists c2 on public.parties; drop policy if exists c3 on public.parties; drop policy if exists c4 on public.parties;
drop policy if exists m1 on public.stock_movements; drop policy if exists m2 on public.stock_movements;
create policy p1 on public.products for select to anon,authenticated using(true); create policy p2 on public.products for insert to anon,authenticated with check(true); create policy p3 on public.products for update to anon,authenticated using(true) with check(true); create policy p4 on public.products for delete to anon,authenticated using(true);
create policy c1 on public.parties for select to anon,authenticated using(true); create policy c2 on public.parties for insert to anon,authenticated with check(true); create policy c3 on public.parties for update to anon,authenticated using(true) with check(true); create policy c4 on public.parties for delete to anon,authenticated using(true);
create policy m1 on public.stock_movements for select to anon,authenticated using(true); create policy m2 on public.stock_movements for insert to anon,authenticated with check(true);
